// Snippet 1: Basic External Linkage (Default behavior)
// Requires definition in one compilation unit (A)
// and declaration (using extern) in another (B).
// --- Unit A (Definition) ---
int application_status = 0;
void start_engine() { /* ... */ }

// --- Unit B (Reference) ---
extern int application_status; // Declaration for the linker
extern void start_engine();     // Matches Unit A's definition

void init() {
    application_status = 1;
    start_engine();
}

// Snippet 2: Internal Linkage (Hiding Symbols)
// Prevents symbol definition from being resolved externally.
// --- Unit A ---
static int local_counter = 5; // C style internal linkage

namespace {
    // C++ style internal linkage (via anonymous namespace)
    void private_utility() { /* ... */ }
}

// --- Unit B ---
// extern int local_counter; // Linker error: cannot resolve
// Cannot reference symbols defined internally in Unit A

// Snippet 3: `extern "C"` (Resolving C++/C Conflicts)
// Forces non-mangled symbol names for cross-language linking.
extern "C" {
    // Defines an external symbol using C linkage conventions
    void shared_interface_call(int x);

    int shared_config = 10;
}

// In a C source file, these are referenced simply:
extern void shared_interface_call(int x);
